    #Node Map Range
    def interpolate_NEW(
        self,
        to_min: Vector=None,
        to_max: Vector=None,
        steps: Vector=None,
        interpolation_type: T_INTERPOLATION_TYPE_1='LINEAR',
        clamp: bool=True):
        """Node Map Range.
        
        Jump: False

        **Fixed inputs**

        - self on socket 'Vector'
        - Socket 'From Min' set to 0.0
        - Socket 'From Max' set to 1.0
        - parameter 'data_type' = 'FLOAT_VECTOR'

        Parameters
        ----------
        to_min : Vector, optional
            Socket 'To Min' (default: None)
        to_max : Vector, optional
            Socket 'To Max' (default: None)
        steps : Vector, optional
            Socket 'Steps' (default: None)
        interpolation_type : {'LINEAR', 'STEPPED', 'SMOOTHSTEP', 'SMOOTHERSTEP'}, optional
            Node parameter 'interpolation_type' (default: 'LINEAR')
        clamp : bool, optional
            Node parameter 'clamp' (default: True)

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {
            'ID_Vector': self, 'From Min': 0.0, 'From Max': 1.0, 'ID_To_Min_FLOAT3': to_min,
            'ID_To_Max_FLOAT3': to_max, 'ID_Steps_FLOAT3': steps}

        node = Node(
            'Map Range',
            named_sockets=named_sockets,
            interpolation_type=interpolation_type,
            data_type='FLOAT_VECTOR',
            clamp=clamp)
        return node._out

    #Node Switch
    def switch_false( self, switch: Boolean=None, false: Vector=None):
        """Node Switch.
        
        Jump: False

        **Fixed inputs**

        - self on socket 'True'
        - parameter 'input_type' = 'VECTOR'

        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Vector, optional
            Socket 'False' (default: None)

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {'ID_True': self, 'ID_Switch': switch, 'ID_False': false}

        node = Node( 'Switch', named_sockets=named_sockets, input_type='VECTOR')
        return node._out
